+      see scripts/regen_site_store_block.dart ──────────────────────────── */
+/* .nav .store-badge out-specifies `.nav a` (dim) — the money link is
+   official-badge black in every state. flex:none + nowrap = the E1 floor:
+   icon+«App Store» never truncates to icon-only, whatever the viewport. */
+.nav .store-badge {
+  display: inline-flex;
+  align-items: center;
+  gap: 6px;
+  flex: none;
+  padding: 5px 11px;
+  border: 1px solid rgba(255, 255, 255, 0.28);
+  border-radius: 8px;
+  background: #000;
+  color: #f5f5f7;
+  font-size: 0.85rem;
+  font-weight: 600;
+  white-space: nowrap;
+}
+.nav .store-badge:hover {
+  text-decoration: none;
+  border-color: var(--accent);
+  color: #fff;
+}
+.store-badge-mark { flex: none; }
+/* Hero hierarchy (OQ1 lean): the store CTA leads on mobile; on desktop the
+   CLI audience lands here, so «Try it in your browser» stays the only
+   primary and the store CTA demotes to a plain button. 1081 = the nav
+   collapse breakpoint (site/styles.css): the whole ≤1080 band is the
+   mobile experience. */
+@media (min-width: 1081px) {
+  .cta-row .btn-store-hero {
+    background: none;
+    border: 1px solid var(--border-bright);
+    color: var(--text);
+  }
+  .cta-row .btn-store-hero:hover { border-color: var(--accent); }
+}
 .store-frames {
   display: grid;
   grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));

