        const onData = (d) => {
          if (bound) return; // banner seen — handler is detached below anyway
          buf += String(d);
          const m = buf.match(/http:\/\/127\.0\.0\.1:(\d+)/);
          if (m) {
            bound = Number(m[1]);
            resolve(bound);
          }
        };
        proc.stderr.on('data', onData);
        setTimeout(() => resolve(0), 3000);
      });
    }
