];
// The menu collapse breakpoint is 1080px (re-measured for gh-881: the
// 11-link row + header badge fits from ~1050px). Keep this in sync with
// site/styles.css.
const MENU_MAX_WIDTH = 1080;

let failures = 0;
let checks = 0;
function ok(name, cond, detail = '') {
  checks++;
