/// The view-model of the in-app Get banner (AC4): every URL and label
/// the web/macOS banner renders. Built from a [LinksConfig] — the widget
/// never hard-codes a store URL.
final class StoreBannerView {
  const StoreBannerView({
    required this.appstoreUrl,
    r…

    'cmd-install': { title: 'Windows Command Prompt — install Fa', cmd: 'curl -fsSL "https://fa1.dev/install.bat" -o install.bat && install.bat' },
    'pub': { title: 'pub.dev direct', cmd: 'dart pub global activate flutter_agent_harness' }
  };
  var installSelect = document.getElementById('install-method');
  var installTitle = document.getElementById('install-command-title');
  var installText = document.getElementById('install-command-text');
  if (installSelect && installTitle && installText) {
    installSelect.addEventListener('change', function () {
      var choice = installCommands[installSelect.value];
      if (!choice) { return; }
      installTitle.textContent = choice.title;
      installText.textContent = choice.cmd;
      track('install_method_selected', { method: installSelect.value });
    });
  }

  /* ── Mobile disclosure menu (gh-756) ──────────────────────────────── */
  var nav = document.querySelector('.nav');
  var navToggle = document.querySelector('.nav-toggle');
  var navMenu = document.getElementById('nav-menu');

  // Anchor jumps must land clear of the sticky header: size scroll-padding
  // to the LIVE header height (it differs wrapped vs one-row) and re-check
  // on resize. Inline style overrides the CSS fallback in styles.css.
  function syncScrollPadding() {
    if (!nav) { return; }
    var h = Math.ceil(nav.getBoundingClientRect().height);
    document.documentElement.style.scrollPaddingTop = (h + 8) + 'px';
  }
  syncScrollPadding();
  var paddingTicking = false;
  window.addEventListener('resize', function () {
    if (paddingTicking) { return; }
    paddingTicking = true;
    setTimeout(function () { syncScrollPadding(); paddingTicking = false; }, 120);
  });

  if (nav && navToggle && navMenu) {
    navToggle.hidden = false; // CSS decides visibility (html.js + ≤1080px)
    function setMenu(open) {
      if (open) { nav.setAttribute('data-open', ''); }
      else { nav.removeAttribute('data-open'); }
      navToggle.setAttribute('aria-expanded', open ? 'true' : 'false');
      syncScrollPadding();
    }
    navToggle.addEventListener('click', function () {
      setMenu(navToggle.getAttribute('aria-expanded') !== 'true');
    });
    // Esc closes and returns focus to the toggle.
    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && nav.hasAttribute('data-open')) {
        setMenu(false);
        navToggle.focus();
      }
